-- ============================================================================
-- ATS SAAS · Fase 3 · Gastos operacionales y administrativos del Excel
--
-- Ambas tablas estaban VACIAS (0 filas), asi que esta es la carga inicial:
-- 295 gastos operacionales y 82 administrativos.
--
-- Requiere 0014 aplicada: con el catalogo anterior, 195 de estas filas no
-- habrian encontrado su categoria. El left join deja categoria_costo_id en
-- null si alguna no calza, en vez de perder la fila; el EERR las muestra en
-- la linea 0.0 y el panel de control las lista.
--
-- total es columna generada: se insertan monto_neto e iva.
-- Re-ejecutable: el NOT EXISTS evita duplicar.
-- ============================================================================

begin;

create temp table _go_imp (
  fecha date, categoria text, subcategoria text, proveedor text, proyecto_servicio text,
  descripcion text, monto_neto numeric(14,2), iva numeric(14,2), facturado_ats text, n_factura text,
  medio_pago text, tipo_costo text, comentario text, km numeric(10,1), litros numeric(10,2)
) on commit drop;


  fecha, categoria_costo_id, proveedor, proyecto_servicio, descripcion, monto_neto, iva,
  facturado_ats, n_factura, medio_pago, tipo_costo, comentario, km, litros)
select i.fecha, cc.id, i.proveedor, i.proyecto_servicio, i.descripcion, i.monto_neto,
  i.iva, i.facturado_ats, i.n_factura, i.medio_pago, i.tipo_costo, i.comentario, i.km, i.litros
from _go_imp i
left join public.categorias_costo cc
  on cc.categoria = i.categoria and cc.subcategoria = i.subcategoria
where not exists (
  select 1 from public.gastos_operacionales g
  where g.fecha = i.fecha and g.monto_neto = i.monto_neto
    and coalesce(g.descripcion,'') = coalesce(i.descripcion,'')
    and coalesce(g.proveedor,'') = coalesce(i.proveedor,'')
);

create temp table _ga_imp (
  fecha date, descripcion text, categoria text, subcategoria text, monto_neto numeric(14,2),
  iva numeric(14,2), facturado_ats text, medio_pago text, tipo_costo text, observaciones text
) on commit drop;

